import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 8;

const FONT_DISPLAY = "'GT Walsheim', Inter, sans-serif";
const FONT_BODY = "Inter, sans-serif";

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ---------------------------------------------------------------------------
// SCENE 1 — Hero: "Introducing Actors v3"
// ---------------------------------------------------------------------------
const SceneHero: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const base = Math.min(width, height);

  // Eyebrow drops in first
  const eyebrowIn = springIn(frame, fps, 2, "SNAPPY");
  // Hero title — SNAPPY, compound reveal
  const titleIn = springIn(frame, fps, 6, "SNAPPY");
  // Highlight pill border drawing
  const highlightIn = springIn(frame, fps, 18, "LIQUID");
  // Subhead — GENTLE, settles in last
  const subIn = springIn(frame, fps, 28, "GENTLE");

  // Ambient drift for hold
  const titleDriftY = ambientDrift(frame, 2.5, 110, "hero-title");
  const eyebrowDriftX = ambientDrift(frame, 1.5, 130, "hero-eyebrow");

  const titleTY = interpolate(titleIn, [0, 1], [50, 0]);
  const titleSC = interpolate(titleIn, [0, 1], [0.94, 1]);
  const titleBL = interpolate(titleIn, [0, 1], [10, 0]);

  return (
    <AbsoluteFill style={{ fontFamily: FONT_DISPLAY, backgroundColor: COLORS.bg }}>
      <Background />

      {/* Subtle radial accent glow, top-right */}
      <div
        style={{
          position: "absolute",
          right: "-12%",
          top: "-10%",
          width: base * 0.7,
          height: base * 0.7,
          borderRadius: "50%",
          background: `radial-gradient(closest-side, ${COLORS.orangeTint}, transparent 70%)`,
          filter: "blur(40px)",
          opacity: 0.55,
        }}
      />

      {/* Off-center anchored hero column */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "26%",
          maxWidth: "78%",
          display: "flex",
          flexDirection: "column",
          gap: base * 0.022,
          transform: `translateY(${titleDriftY}px)`,
        }}
      >
        {/* Eyebrow */}
        <div
          style={{
            fontFamily: FONT_BODY,
            fontWeight: 600,
            fontSize: base * 0.022,
            color: COLORS.orange,
            letterSpacing: "0.22em",
            textTransform: "uppercase",
            opacity: eyebrowIn,
            transform: `translateX(${interpolate(eyebrowIn, [0, 1], [-20, 0]) + eyebrowDriftX}px)`,
          }}
        >
          New · Product Release
        </div>

        {/* Hero title */}
        <div
          style={{
            fontFamily: FONT_DISPLAY,
            fontWeight: 600,
            fontSize: base * 0.14,
            color: COLORS.text,
            lineHeight: 0.95,
            letterSpacing: "-0.035em",
            opacity: titleIn,
            transform: `translateY(${titleTY}px) scale(${titleSC})`,
            filter: `blur(${titleBL}px)`,
          }}
        >
          Introducing{" "}
          <span
            style={{
              display: "inline-block",
              background: COLORS.orangeTint,
              borderBottom: `${Math.max(3, base * 0.0045)}px solid ${COLORS.orange}`,
              padding: `0 ${base * 0.018}px`,
              borderRadius: base * 0.012,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            }}
          >
            Actors v3
          </span>
        </div>

        {/* Subhead */}
        <div
          style={{
            fontFamily: FONT_BODY,
            fontWeight: 400,
            fontSize: base * 0.026,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            lineHeight: 1.3,
            maxWidth: base * 1.0,
            marginTop: base * 0.018,
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [16, 0])}px)`,
          }}
        >
          The next generation of programmable web automation.
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ---------------------------------------------------------------------------
// SCENE 2 — Three benefits
// ---------------------------------------------------------------------------
const BENEFITS = [
  { label: "Faster cold starts", descriptor: "Sub-second startup, every run" },
  { label: "Native MCP support", descriptor: "Plug straight into any AI agent" },
  { label: "Pay per second", descriptor: "Only pay for the time you use" },
];

const CheckIcon: React.FC<{ size: number; progress: number }> = ({ size, progress }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" style={{ flexShrink: 0 }}>
    <circle
      cx={12}
      cy={12}
      r={11}
      fill={COLORS.orangeTint}
      opacity={progress}
    />
    <path
      d="M6 12.5 L10.5 17 L18 8"
      stroke={COLORS.orange}
      strokeWidth={2.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
      strokeDasharray={28}
      strokeDashoffset={interpolate(progress, [0, 1], [28, 0])}
    />
  </svg>
);

const BenefitRow: React.FC<{
  item: (typeof BENEFITS)[number];
  index: number;
  base: number;
  frame: number;
}> = ({ item, index, base, frame }) => {
  const p = staggeredSpring(frame, fps, index, 14, 8, "ELASTIC");
  const driftY = ambientDrift(frame, 1.2, 90 + index * 17, `row-${index}`);

  return (
    <div
      style={{
        display: "flex",
        alignItems: "flex-start",
        gap: base * 0.022,
        opacity: p,
        transform: `translateX(${interpolate(p, [0, 1], [-base * 0.025, 0])}px) translateY(${driftY}px)`,
      }}
    >
      <div style={{ marginTop: base * 0.006 }}>
        <CheckIcon size={base * 0.04} progress={p} />
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: base * 0.004 }}>
        <div
          style={{
            fontFamily: FONT_DISPLAY,
            fontWeight: 600,
            fontSize: base * 0.046,
            color: COLORS.text,
            letterSpacing: "-0.015em",
            lineHeight: 1.1,
          }}
        >
          {item.label}
        </div>
        <div
          style={{
            fontFamily: FONT_BODY,
            fontWeight: 400,
            fontSize: base * 0.022,
            color: COLORS.textMuted,
            lineHeight: 1.3,
            letterSpacing: "-0.005em",
          }}
        >
          {item.descriptor}
        </div>
      </div>
    </div>
  );
};

const SceneBenefits: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const titleIn = springIn(frame, fps, 2, "SNAPPY");
  const cardIn = springIn(frame, fps, 8, "LIQUID");

  const titleDriftY = ambientDrift(frame, 2, 100, "ben-title");

  return (
    <AbsoluteFill style={{ fontFamily: FONT_DISPLAY, backgroundColor: COLORS.bg }}>
      <Background />

      {/* Decorative accent glow bottom-left */}
      <div
        style={{
          position: "absolute",
          left: "-10%",
          bottom: "-15%",
          width: base * 0.55,
          height: base * 0.55,
          borderRadius: "50%",
          background: `radial-gradient(closest-side, ${COLORS.orangeTint}, transparent 70%)`,
          filter: "blur(50px)",
          opacity: 0.45,
        }}
      />

      {/* Asymmetric layout: title left-anchored, card right-aligned */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          padding: `${base * 0.06}px ${base * 0.07}px`,
          display: "grid",
          gridTemplateColumns: "1fr 1.15fr",
          alignItems: "center",
          gap: base * 0.04,
        }}
      >
        {/* Left: short headline */}
        <div
          style={{
            opacity: titleIn,
            transform: `translateY(${interpolate(titleIn, [0, 1], [22, 0]) + titleDriftY}px)`,
            display: "flex",
            flexDirection: "column",
            gap: base * 0.018,
          }}
        >
          <div
            style={{
              fontFamily: FONT_BODY,
              fontWeight: 600,
              fontSize: base * 0.02,
              color: COLORS.orange,
              letterSpacing: "0.22em",
              textTransform: "uppercase",
            }}
          >
            What's new
          </div>
          <div
            style={{
              fontFamily: FONT_DISPLAY,
              fontWeight: 600,
              fontSize: base * 0.072,
              color: COLORS.text,
              letterSpacing: "-0.03em",
              lineHeight: 1.02,
            }}
          >
            Built for{" "}
            <span
              style={{
                background: COLORS.orangeTint,
                borderBottom: `${Math.max(2, base * 0.003)}px solid ${COLORS.orange}`,
                padding: `0 ${base * 0.012}px`,
                borderRadius: base * 0.008,
              }}
            >
              agents
            </span>
            .
          </div>
        </div>

        {/* Right: card with checklist */}
        <div
          style={{
            backgroundColor: "rgba(255,255,255,0.04)",
            border: `1px solid ${COLORS.border}`,
            borderRadius: base * 0.018,
            padding: `${base * 0.04}px ${base * 0.038}px`,
            display: "flex",
            flexDirection: "column",
            gap: base * 0.028,
            opacity: cardIn,
            transform: `translateY(${interpolate(cardIn, [0, 1], [28, 0])}px) scale(${interpolate(cardIn, [0, 1], [0.96, 1])})`,
            backdropFilter: "blur(12px)",
            boxShadow: "0 24px 64px rgba(0,0,0,0.35)",
          }}
        >
          {BENEFITS.map((item, i) => (
            <BenefitRow key={i} item={item} index={i} base={base} frame={frame} />
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ---------------------------------------------------------------------------
// SCENE 3 — Sign-off "Build. Run. Scale."
// ---------------------------------------------------------------------------
const TAGLINE_WORDS = ["Build.", "Run.", "Scale."];

const SceneSignoff: React.FC = () => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const eyebrowIn = springIn(frame, fps, 2, "SNAPPY");
  const ctaIn = springIn(frame, fps, 28, "LIQUID");

  // Per-word stagger
  const wordDriftSeeds = ["w0", "w1", "w2"];

  // Subtle CTA breathe
  const ctaBreathe = ambientDrift(frame, 0.012, 60, "cta-breathe");
  const ctaScale = 1 + ctaBreathe;

  return (
    <AbsoluteFill style={{ fontFamily: FONT_DISPLAY, backgroundColor: COLORS.bg }}>
      <Background />

      {/* Centered radial glow */}
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: base * 0.9,
          height: base * 0.9,
          borderRadius: "50%",
          transform: "translate(-50%, -50%)",
          background: `radial-gradient(closest-side, ${COLORS.orangeTint}, transparent 70%)`,
          filter: "blur(60px)",
          opacity: 0.35,
        }}
      />

      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: base * 0.035,
          padding: `0 ${base * 0.08}px`,
        }}
      >
        {/* Eyebrow */}
        <div
          style={{
            fontFamily: FONT_BODY,
            fontWeight: 600,
            fontSize: base * 0.022,
            color: COLORS.orange,
            letterSpacing: "0.25em",
            textTransform: "uppercase",
            opacity: eyebrowIn,
            transform: `translateY(${interpolate(eyebrowIn, [0, 1], [-14, 0])}px)`,
          }}
        >
          Actors v3 · Out now
        </div>

        {/* Tagline — per-word kinetic reveal */}
        <div
          style={{
            display: "flex",
            gap: base * 0.028,
            alignItems: "baseline",
            justifyContent: "center",
            flexWrap: "wrap",
          }}
        >
          {TAGLINE_WORDS.map((word, i) => {
            const wp = staggeredSpring(frame, fps, i, 8, 6, "SNAPPY");
            const isAccent = i === TAGLINE_WORDS.length - 1;
            const wordDriftY = ambientDrift(frame, 2, 95 + i * 22, wordDriftSeeds[i]);

            const tY = interpolate(wp, [0, 1], [60, 0]);
            const sc = interpolate(wp, [0, 1], [0.88, 1]);
            const bl = interpolate(wp, [0, 1], [12, 0]);

            return (
              <div
                key={i}
                style={{
                  fontFamily: FONT_DISPLAY,
                  fontWeight: 600,
                  fontSize: base * 0.14,
                  color: isAccent ? COLORS.orange : COLORS.text,
                  lineHeight: 0.95,
                  letterSpacing: "-0.035em",
                  opacity: wp,
                  transform: `translateY(${tY + wordDriftY}px) scale(${sc})`,
                  filter: `blur(${bl}px)`,
                }}
              >
                {word}
              </div>
            );
          })}
        </div>

        {/* CTA pill */}
        <div
          style={{
            marginTop: base * 0.02,
            opacity: ctaIn,
            transform: `translateY(${interpolate(ctaIn, [0, 1], [16, 0])}px) scale(${ctaScale})`,
          }}
        >
          <div
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: base * 0.014,
              border: `${Math.max(1.5, base * 0.0022)}px solid ${COLORS.orange}`,
              borderRadius: 999,
              padding: `${base * 0.014}px ${base * 0.032}px`,
              fontFamily: FONT_DISPLAY,
              fontWeight: 600,
              fontSize: base * 0.024,
              color: COLORS.orange,
              letterSpacing: "-0.005em",
              backgroundColor: "rgba(248,102,6,0.06)",
            }}
          >
            apify.com/actors-v3
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ---------------------------------------------------------------------------
// MAIN COMPOSITION
// ---------------------------------------------------------------------------
// Scene durations at 25fps (~8 seconds total)
// Hero: 70 frames (~2.8s)
// Benefits: 80 frames (~3.2s)
// Signoff: 60 frames (~2.4s)
// Total raw: 210 frames. Minus 2 transitions of 8 = 194 frames (~7.76s).
const SCENE_HERO_FRAMES = 70;
const SCENE_BENEFITS_FRAMES = 80;
const SCENE_SIGNOFF_FRAMES = 60;

export const durationInFrames =
  SCENE_HERO_FRAMES + SCENE_BENEFITS_FRAMES + SCENE_SIGNOFF_FRAMES - TRANSITION * 2;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_HERO_FRAMES + TRANSITION}>
        <SceneHero />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_BENEFITS_FRAMES + TRANSITION}>
        <SceneBenefits />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_SIGNOFF_FRAMES}>
        <SceneSignoff />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
